files.content:
:root {
  --px-border: 4px solid #000;
  --px-shadow: 4px 4px 0 #000;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #1a1c2c;
  font-family: monospace;
  color: #000;
}

.calc {
  background: #f0d9b5;
  padding: 2rem;
  border: var(--px-border);
  box-shadow: var(--px-shadow);
  image-rendering: pixelated;
  width: min(90vw, 340px);
}

h1 {
  margin: 0 0 1rem;
  font-size: 1.5rem;
  text-align: center;
  text-transform: uppercase;
}

.field {
  display: flex;
  flex-direction: column;
  margin-bottom: 1rem;
}

label {
  font-weight: bold;
  margin-bottom: 0.25rem;
}

input,
select,
button,
output {
  font: inherit;
  border: 3px solid #000;
  background: #fff;
  padding: 0.5rem;
  box-shadow: 3px 3px 0 #000;
  border-radius: 0;
}

input:focus,
select:focus,
button:focus {
  outline: 3px solid #ffcc00;
  outline-offset: 2px;
}

button {
  background: #ffcc00;
  cursor: pointer;
  width: 100%;
  margin-top: 0.5rem;
  font-weight: bold;
}

button:active {
  box-shadow: none;
  transform: translate(3px, 3px);
}

.result-field output {
  display: block;
  background: #fff;
  min-height: 2rem;
  word-break: break-all;
}

const left = document.getElementById('left');
const right = document.getElementById('right');
const operation = document.getElementById('operation');
const result = document.getElementById('result');

function readNumber(input) {
  const raw = input.value.trim();
  if (raw === '') return null;
  const num = Number(raw);
  return Number.isFinite(num) ? num : null;
}

document.getElementById('calculate').addEventListener('click', () => {
  const a = readNumber(left);
  const b = readNumber(right);

  if (a === null || b === null) {
    result.textContent = 'Error';
    return;
  }

  if (operation.value === 'divide' && b === 0) {
    result.textContent = 'Error';
    return;
  }

  let answer;
  switch (operation.value) {
    case 'add':
      answer = a + b;
      break;
    case 'subtract':
      answer = a - b;
      break;
    case 'multiply':
      answer = a * b;
      break;
    case 'divide':
      answer = a / b;
      break;
    default:
      result.textContent = 'Error';
      return;
  }

  result.textContent = String(answer);
});
